<?php
header('Content-Type: application/json');
require_once __DIR__ . '/../lib.php';
require_once __DIR__ . '/../../public/db_connect.php';
require_once __DIR__ . '/../classes/ShiftPeriodConfig.php';  // Only allow authenticated users
require_login();  $me = current_user();
$station_id = user_station_id();
$role = role_key($me['role'] ?? '');  try {  $pdo = getPDO();  $shift_config = getShiftPeriodConfig($pdo, $station_id);  $method = $_SERVER['REQUEST_METHOD'];  $action = $_GET['action'] ?? '';  switch ($method) {  case 'GET':  switch ($action) {  case 'current':  // Get current shift  $current_shift = $shift_config->getCurrentShift();  echo json_encode([  'success' => true,  'data' => $current_shift  ]);  break;  case 'all':  // Get all shift periods  $shifts = $shift_config->getShiftPeriods();  echo json_encode([  'success' => true,  'data' => $shifts  ]);  break;  case 'options':  // Get shift period options for select dropdown  $options = $shift_config->getShiftPeriodOptions();  echo json_encode([  'success' => true,  'data' => $options  ]);  break;  case 'validate':  // Validate shift key  $shift_key = $_GET['shift_key'] ?? '';  $is_valid = $shift_config->isValidShiftKey($shift_key);  echo json_encode([  'success' => true,  'data' => [  'is_valid' => $is_valid,  'shift_key' => $shift_key  ]  ]);  break;  default:  // Default: return all shift periods  $shifts = $shift_config->getShiftPeriods();  echo json_encode([  'success' => true,  'data' => $shifts  ]);  }  break;  case 'POST':  // Only managers and admins can modify shift periods  if (!in_array($role, ['manager', 'admin', 'superadmin'])) {  http_response_code(403);  echo json_encode([  'success' => false,  'message' => 'Access denied. Only managers and admins can modify shift periods.'  ]);  exit;  }  $input = json_decode(file_get_contents('php://input'), true);  switch ($action) {  case 'add':  // Add new shift period  $required_fields = ['shift_key', 'shift_name', 'start_time', 'end_time'];  foreach ($required_fields as $field) {  if (!isset($input[$field]) || empty($input[$field])) {  http_response_code(400);  echo json_encode([  'success' => false,  'message' => "Missing required field: $field"  ]);  exit;  }  }  $result = $shift_config->addShiftPeriod($input);  if ($result) {  echo json_encode([  'success' => true,  'message' => 'Shift period added successfully'  ]);  } else {  http_response_code(500);  echo json_encode([  'success' => false,  'message' => 'Failed to add shift period'  ]);  }  break;  case 'update':  // Update existing shift period  if (!isset($input['id']) || empty($input['id'])) {  http_response_code(400);  echo json_encode([  'success' => false,  'message' => 'Missing shift period ID'  ]);  exit;  }  $result = $shift_config->updateShiftPeriod($input['id'], $input);  if ($result) {  echo json_encode([  'success' => true,  'message' => 'Shift period updated successfully'  ]);  } else {  http_response_code(500);  echo json_encode([  'success' => false,  'message' => 'Failed to update shift period'  ]);  }  break;  case 'delete':  // Delete shift period  if (!isset($input['id']) || empty($input['id'])) {  http_response_code(400);  echo json_encode([  'success' => false,  'message' => 'Missing shift period ID'  ]);  exit;  }  $result = $shift_config->deleteShiftPeriod($input['id']);  if ($result) {  echo json_encode([  'success' => true,  'message' => 'Shift period deleted successfully'  ]);  } else {  http_response_code(500);  echo json_encode([  'success' => false,  'message' => 'Failed to delete shift period'  ]);  }  break;  default:  http_response_code(400);  echo json_encode([  'success' => false,  'message' => 'Invalid action'  ]);  }  break;  default:  http_response_code(405);  echo json_encode([  'success' => false,  'message' => 'Method not allowed'  ]);  }  } catch (Exception $e) {  error_log("Shift periods API error: " . $e->getMessage());  http_response_code(500);  echo json_encode([  'success' => false,  'message' => 'Internal server error'  ]);
}
?>
